class Solution {
    public int findSmallestInteger(int[] nums,int value){
        int[] count=new int[value];
        for(int number:nums)count[(number%value+value)%value]++;
        for(int candidate=0;;candidate++){
            int residue=candidate%value;
            if(count[residue]==0)return candidate;
            count[residue]--;
        }
    }
}

code.kotlin:
class Solution {
    fun findSmallestInteger(nums:IntArray,value:Int):Int{
        val count=IntArray(value);
        for(number in nums)count[(number%value+value)%value]++;
        var candidate=0;
        while(true){
            val residue=candidate%value;
            if(count[residue]==0)return candidate;
            count[residue]--;
            candidate++
        }
    }
}

code.cpp:
class Solution {
    public:int findSmallestInteger(vector<int>& nums,int value){
        vector<int> count(value);
        for(int number:nums)++count[(number%value+value)%value];
        for(int candidate=0;;++candidate){
            int residue=candidate%value;
            if(!count[residue])return candidate;
            --count[residue];
        }
    }
};
